const labels={'materia-prima':'Matéria-prima',insumos:'Insumos / EPIs',manutencao:'Manutenção',diesel:'Diesel',areiaamigos:'Areia Amigos',areiaadmin:'Administrar Areia Amigos','cimento-granel':'Cimento a granel','cimento-ensacado':'Cimento ensacado',fornecedores:'Agenda de Fornecedores'};
const form=document.querySelector('#user-form'),messageBox=document.querySelector('#message'),list=document.querySelector('#users');
let users=[],editing=null;
const esc=s=>String(s??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
function message(text,error=false){messageBox.innerHTML='<p class="status '+(error?'error':'')+'">'+esc(text)+'</p>';}
async function api(path,method='GET',body){const r=await fetch(path,{method,headers:body?{'Content-Type':'application/json'}:{},body:body?JSON.stringify(body):undefined,cache:'no-store'});const j=await r.json();if(r.status===401){location.href='/logout';throw Error('Sessão encerrada. Entre novamente.');}if(!r.ok)throw Error(j.error||'Falha na operação.');return j;}
document.querySelector('#modules').innerHTML=Object.entries(labels).map(([key,label])=>'<label><input type="checkbox" name="permissions" value="'+esc(key)+'"> '+esc(label)+'</label>').join('');
function reset(){editing=null;form.reset();form.elements.user.readOnly=false;form.elements.password.required=true;document.querySelector('#form-title').textContent='Novo usuário';document.querySelector('#password-hint').textContent='mínimo 8 caracteres';document.querySelector('#cancel').hidden=true;document.querySelector('#module-fieldset').disabled=false;}
function edit(u){editing=u;form.reset();form.elements.name.value=u.name;form.elements.user.value=u.user;form.elements.user.readOnly=true;form.elements.password.required=false;for(const box of form.querySelectorAll('[name=permissions]'))box.checked=(u.permissions||[]).includes(box.value);document.querySelector('#module-fieldset').disabled=u.role==='admin';document.querySelector('#form-title').textContent='Editar '+u.user;document.querySelector('#password-hint').textContent='deixe vazia para manter';document.querySelector('#cancel').hidden=false;form.scrollIntoView({behavior:'smooth'});}
async function load(){const data=await api('/api/users');users=data.users||[];document.querySelector('#create-diego').hidden=users.some(u=>u.user.toLowerCase()==='diego');list.innerHTML=users.map(u=>'<div class="row"><div><strong>'+esc(u.name)+'</strong> · '+esc(u.user)+'<p class="muted">'+esc(u.role==='admin'?'Administrador':u.role==='operator'?'Operacional':(u.permissions||[]).map(x=>labels[x]||x).join(', ')||'Sem módulos')+' · '+(u.enabled?'Ativo':'Inativo')+(u.protected?' · Conta protegida':'')+(u.source==='environment'?' · Ambiente':'')+'</p></div><div class="actions">'+(u.source==='environment'?'<span class="muted">Migre para editar</span>':'<button type="button" data-action="edit" data-user="'+esc(u.user)+'">Editar</button>'+(u.protected?'':'<button type="button" class="secondary" data-action="toggle" data-user="'+esc(u.user)+'">'+(u.enabled?'Inativar':'Reativar')+'</button><button type="button" class="danger" data-action="delete" data-user="'+esc(u.user)+'">Excluir</button>'))+'</div></div>').join('');}
form.addEventListener('submit',async e=>{e.preventDefault();const f=new FormData(form),payload={name:String(f.get('name')).trim()},password=String(f.get('password')||'');if(password)payload.password=password;if(!editing){payload.user=String(f.get('user')).trim().toLowerCase();payload.permissions=f.getAll('permissions');}else if(editing.role!=='admin')payload.permissions=f.getAll('permissions');try{await api(editing?'/api/users/'+encodeURIComponent(editing.user):'/api/users',editing?'PATCH':'POST',payload);reset();message('Usuário salvo.');await load();}catch(error){message(error.message,true);}});
document.querySelector('#cancel').onclick=reset;
document.querySelector('#create-diego').onclick=()=>{reset();form.elements.user.value='diego';form.elements.user.readOnly=true;form.elements.name.value='Diego';document.querySelector('#module-fieldset').disabled=true;form.elements.password.focus();message('Defina a senha inicial para criar o administrador protegido Diego.');};
document.querySelector('#migrate').onclick=async()=>{if(!confirm('Migrar as contas do ambiente para o banco? Será necessário entrar novamente.'))return;try{const r=await api('/api/users/migrate-environment','POST',{});if(r.count){location.href='/logout';return;}message('Nenhuma conta pendente de migração.');await load();}catch(e){message(e.message,true);}};
list.onclick=async event=>{const b=event.target.closest('[data-action]');if(!b)return;const u=users.find(x=>x.user===b.dataset.user);if(!u)return;if(b.dataset.action==='edit')return edit(u);try{if(b.dataset.action==='delete'){if(!confirm('Excluir o usuário '+u.user+'?'))return;await api('/api/users/'+encodeURIComponent(u.user),'DELETE');message('Usuário excluído.');}else{await api('/api/users/'+encodeURIComponent(u.user),'PATCH',{enabled:!u.enabled});message(u.enabled?'Usuário inativado.':'Usuário reativado.');}await load();}catch(e){message(e.message,true);}};
load().catch(e=>message(e.message,true));
async function loadOnline(){try{const data=await api('/api/online');document.querySelector('#online').innerHTML=(data.users||[]).map(u=>'<p>'+esc(u.name)+' · '+esc(u.user)+'</p>').join('')||'<p class="muted">Nenhum usuário ativo.</p>';}catch(error){document.querySelector('#online').textContent='Não foi possível consultar as sessões.';}}
loadOnline();setInterval(loadOnline,30000);
function applyTheme(){document.documentElement.dataset.theme=localStorage.getItem('colafix-theme')==='dark'?'dark':'light';}
document.querySelector('#theme').onclick=()=>{localStorage.setItem('colafix-theme',document.documentElement.dataset.theme==='dark'?'light':'dark');applyTheme();};applyTheme();
